:root {
      --bg-main: #fdf9f3;
      --bg-section: #ffffff;
      --accent: #8b3a3a;
      --accent-soft: #c28a5b;
      --accent-green: #6c8b4f;
      --accent-deep: #3b4b2a;
      --text-main: #222222;
      --text-soft: #555555;
      --border-soft: #e3d7c5;
      --shadow-soft: 0 18px 45px rgba(0,0,0,0.06);
      --radius-lg: 24px;
      --radius-md: 16px;
      --radius-pill: 999px;
      --transition-fast: 0.25s ease;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #fffaf2 0, #f6f1e7 40%, #f1ebdf 100%);
      color: var(--text-main);
      direction: rtl;
      scroll-behavior: smooth;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    header {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(14px);
      background: rgba(253,249,243,0.92);
      border-bottom: 1px solid rgba(0,0,0,0.03);
    }

    .nav {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0.75rem 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .nav-left {
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }

    .logo-text {
      display: flex;
      flex-direction: column;
      font-size: 0.9rem;
      line-height: 1.3;
    }

    .logo-text strong { font-size: 1rem; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      font-size: 0.9rem;
    }

    .nav-links a {
      position: relative;
      padding-bottom: 0.15rem;
    }

    .nav-links a::after {
      content: "";
      position: absolute;
      right: 0;
      bottom: 0;
      width: 0;
      height: 2px;
      background: linear-gradient(90deg, var(--accent-green), var(--accent-soft));
      transition: width var(--transition-fast);
    }

    .nav-links a:hover::after { width: 100%; }

    .nav-cta {
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }


    .btn-primary {
      border-radius: var(--radius-pill);
      padding: 0.55rem 1.4rem;
      border: none;
      cursor: pointer;
      background: linear-gradient(135deg, var(--accent-green), var(--accent-soft));
      color: #fff;
      font-size: 0.9rem;
      font-weight: 600;
      box-shadow: 0 12px 30px rgba(108,139,79,0.35);
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      transition: transform var(--transition-fast), box-shadow var(--transition-fast), filter var(--transition-fast);
    }

    .btn-primary:hover {
      transform: translateY(-1px);
      filter: brightness(1.05);
      box-shadow: 0 16px 40px rgba(108,139,79,0.45);
    }

    .btn-outline {
      border-radius: var(--radius-pill);
      padding: 0.5rem 1.2rem;
      border: 1px solid rgba(0,0,0,0.08);
      background: rgba(255,255,255,0.85);
      font-size: 0.85rem;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      transition: background var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);
    }

    .btn-outline:hover {
      background: #ffffff;
      border-color: rgba(0,0,0,0.16);
      box-shadow: 0 10px 25px rgba(0,0,0,0.06);
    }

    main {
      max-width: 1200px;
      margin: 0 auto;
      padding: 1.5rem;
    }

    /* HERO */
    .hero {
      margin-top: 1.5rem;
      border-radius: 30px;
      overflow: hidden;
      position: relative;
      min-height: 460px;
      display: grid;
      grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
      background: linear-gradient(135deg, #fdf9f3 0, #f3f7ec 40%, #f0f4ea 100%);
      box-shadow: 0 26px 70px rgba(0,0,0,0.12);
      isolation: isolate;
    }

    .hero-media {
      position: relative;
      overflow: hidden;
      perspective: 1200px;
      min-height: 340px;
    }

    /* כאן אתה מדביק את תמונת ההירו (השער + הכרם) */
    .hero-layer-bg {
      position: absolute;
      inset: 0;
      background-image: url("data:image/jpeg;base64,");
      background-size: cover;
      background-position: right center;
      background-repeat: no-repeat;
      }

    /* אם תרצה שכבת שער נפרדת – אפשר לשים כאן תמונה נוספת, אחרת אפשר למחוק את הבלוק הזה */
    .hero-layer-gate {
      position: absolute;
      bottom: -4%;
      right: 8%;
      width: 32%;
      height: 55%;
      background-image: none;
      background-size: cover;
      background-position: center;
      opacity: 0.95;
      filter: drop-shadow(0 18px 40px rgba(0,0,0,0.35));
      transform-origin: center bottom;
      }

    /* שכבת עלים – אם יש לך תמונת עלים, מדביקים כאן, אחרת אפשר למחוק */
    .hero-layer-leaves {
      position: absolute;
      inset: -12% 0 0 0;
      background-image: none;
      background-size: 130%;
      background-position: top center;
      opacity: 0.45;
      pointer-events: none;
      animation: leavesDrift 26s linear infinite alternate;
    }

    .hero-particles {
      position: absolute;
      inset: 0;
      pointer-events: none;
      background-image:
        radial-gradient(circle, rgba(255,255,255,0.7) 0, transparent 55%),
        radial-gradient(circle, rgba(255,255,255,0.5) 0, transparent 55%);
      background-size: 220px 220px, 260px 260px;
      background-position: 10% 20%, 80% 70%;
      opacity: 0.4;
      }

    .hero-content {
      position: relative;
      padding: 2.4rem 2.4rem 2.4rem 2rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 1.5rem;
    }

    @media (min-width: 1100px) {
    .hero-content {
        transform: translateX(-60px);
    }
}

@media (min-width: 1100px) {
  .hero-content {
    margin-right: 180px;
  }
}

    .hero-kicker {
      font-size: 0.85rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent-green);
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
    }

    .hero-kicker span.dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--accent-soft);
    }

    .hero-title {
      font-size: 2.2rem;
      line-height: 1.25;
      max-width: 20ch;
      color: #1f2616;
    }

    .hero-subtitle {
      font-size: 1rem;
      color: #4b4f3a;
      max-width: 40ch;
    }

    .hero-badges {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-top: 0.75rem;
    }

    .badge {
      border-radius: var(--radius-pill);
      padding: 0.3rem 0.8rem;
      font-size: 0.8rem;
      background: rgba(255,255,255,0.9);
      border: 1px solid rgba(0,0,0,0.06);
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      box-shadow: 0 10px 24px rgba(0,0,0,0.04);
    }

    .badge-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: linear-gradient(135deg, #f5d7a1, #f0b35a);
    }

    .hero-meta {
      font-size: 0.8rem;
      color: #5b6147;
      display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
      align-items: center;
    }

    .hero-meta-item {
      display: flex;
      align-items: center;
      gap: 0.4rem;
    }

    .hero-meta-dot {
      width: 4px;
      height: 4px;
      border-radius: 50%;
      background: #9aa87a;
    }
    .hero-cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

    /* ══════════════════════════════════════════
   LUXURY UPGRADE — HEADER + HERO
   ══════════════════════════════════════════ */

/* ── HEADER ──────────────────────────────── */
header {
  position: fixed !important;
  top: 0; left: 0; right: 0;
  z-index: 9999 !important;
  background: #1A2F1A !important;
  transition: background 0.4s ease, box-shadow 0.4s ease;
}
header.scrolled {
  background: #ffffff !important;
  box-shadow: 0 2px 20px rgba(0,0,0,0.10) !important;
}

/* Nav links */
.nav-links a {
  color: #F5F0E6 !important;
  letter-spacing: 0.03em;
}
.nav-links a::after { background: #D4AF37 !important; }
header.scrolled .nav-links a { color: #1A2F1A !important; }

/* Logo text */
.logo-text strong, .logo-text span { color: #F5F0E6 !important; }
header.scrolled .logo-text strong,
header.scrolled .logo-text span   { color: #1A2F1A !important; }

/* Circular logo */
.logo-mark {
  border-radius: 50% !important;
  overflow: hidden !important;
  border: 2px solid #D4AF37 !important;
  width: 62px !important;
  height: 62px !important;
  flex-shrink: 0;
}
.logo-mark img {
  border-radius: 50% !important;
  width: 62px !important;
  height: 62px !important;
  object-fit: cover !important;
  display: block;
}

/* Buttons */
.btn-primary {
  background: #D4AF37 !important;
  color: #1A2F1A !important;
  font-weight: 700 !important;
  border: none !important;
}
.btn-outline {
  border: 1.5px solid #D4AF37 !important;
  color: #D4AF37 !important;
}
header.scrolled .btn-primary {
  background: #1A2F1A !important;
  color: #F5F0E6 !important;
}
header.scrolled .btn-outline {
  border-color: #1A2F1A !important;
  color: #1A2F1A !important;
}

/* Hamburger lines */
.hamburger-btn span { background: #F5F0E6 !important; }
header.scrolled .hamburger-btn span { background: #1A2F1A !important; }

/* Language icon */
.lang-icon-btn svg path,
.lang-icon-btn svg circle,
.lang-icon-btn svg line,
.lang-icon-btn svg ellipse { stroke: #F5F0E6 !important; }
header.scrolled .lang-icon-btn svg path,
header.scrolled .lang-icon-btn svg circle,
header.scrolled .lang-icon-btn svg line,
header.scrolled .lang-icon-btn svg ellipse { stroke: #1A2F1A !important; }

/* Mobile drawer */
.mobile-nav-drawer { background: #1A2F1A !important; }
.mobile-nav-link {
  color: #F5F0E6 !important;
  border-bottom: 1px solid rgba(212,175,55,0.18) !important;
  padding: 1rem 1.5rem !important;
  font-size: 1rem !important;
  letter-spacing: 0.04em;
  transition: color 0.2s;
}
.mobile-nav-link:hover { color: #D4AF37 !important; }

/* ── HERO ─────────────────────────────────── */
main { padding-top: 0 !important; }

.hero {
  position: relative !important;
  width: 100vw !important;
  height: 100vh !important;
  min-height: 100vh !important;
  margin: 0 !important;
  border-radius: 0 !important;
  display: block !important;
  overflow: hidden !important;
  background: #0f1f0f !important;
}
.hero-media {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  min-height: unset !important;
}
.hero-layer-bg {
  position: absolute !important;
  inset: 0 !important;
  background-size: cover !important;
  background-position: center 30% !important;
  background-repeat: no-repeat !important;
  transform: none !important;
  animation: none !important;
  filter: none !important;
}
.hero-layer-gate,
.hero-layer-leaves,
.hero-particles { display: none !important; }

/* Dark gradient overlay — bottom-heavy */
.hero-overlay {
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  background: linear-gradient(
    to top,
    rgba(8,16,8,0.88) 0%,
    rgba(8,16,8,0.52) 38%,
    rgba(8,16,8,0.14) 70%,
    transparent 100%
  ) !important;
  z-index: 1 !important;
}

/* Content — pinned to bottom */
.hero-content {
  position: absolute !important;
  inset: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: flex-end !important;
  align-items: flex-start !important;
  padding: 0 6vw 6vh !important;
  gap: 0.9rem !important;
  z-index: 2 !important;
  width: 100% !important;
  max-width: unset !important;
  box-sizing: border-box !important;
}

/* Kicker */
.hero-kicker {
  color: #D4AF37 !important;
  font-size: 0.72rem !important;
  letter-spacing: 0.22em !important;
  text-transform: uppercase !important;
  font-weight: 600 !important;
  background: none !important;
  border: none !important;
  padding: 0 !important;
}
.hero-kicker span.dot { display: none !important; }

.hero-kicker {
  position: relative;
  z-index: 2;
}

.hero-kicker::before {
  content: "";
  position: absolute;
  inset: -4px -8px; /* מרחיב קצת מסביב לטקסט */
  background: rgba(0,0,0,0.22); /* כהות עדינה מאוד */
  filter: blur(6px); /* טשטוש יוקרתי */
  border-radius: 4px;
  z-index: -1;
}

/* Title */
.hero-title {
  font-size: clamp(2rem, 4.8vw, 3.8rem) !important;
  line-height: 1.22 !important;
  color: #F5F0E6 !important;
  max-width: 18ch !important;
  text-shadow: 0 2px 28px rgba(0,0,0,0.55) !important;
  font-weight: 700 !important;
  margin: 0 !important;
}

/* Subtitle */
.hero-subtitle {
  font-size: clamp(0.88rem, 1.5vw, 1rem) !important;
  color: rgba(245,240,230,0.85) !important;
  max-width: 46ch !important;
  line-height: 1.75 !important;
  text-shadow: 0 1px 10px rgba(0,0,0,0.4) !important;
}

/* Badges */
.hero-badges { display: flex !important; flex-wrap: wrap !important; gap: 0.45rem !important; }
.hero-badge {
  background: rgba(212,175,55,0.12) !important;
  border: 1px solid rgba(212,175,55,0.4) !important;
  color: #D4AF37 !important;
  font-size: 0.72rem !important;
  padding: 0.28rem 0.9rem !important;
  border-radius: 999px !important;
  letter-spacing: 0.07em !important;
  backdrop-filter: blur(4px);
}

/* CTA row */
.hero-cta-row {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 0.75rem !important;
  margin-top: 0.4rem !important;
}

/* כפתור צור קשר – זהוב מלא */
.hero-cta-row .btn-primary {
  background: #D4AF37 !important;
  color: #1A2F1A !important;
  font-weight: 700 !important;
  font-size: 0.92rem !important;
  padding: 0.78rem 2.2rem !important;
  border-radius: 3px !important; /* מרובע */
  border: none !important;
  letter-spacing: 0.05em !important;
  cursor: pointer !important;
}

/* כפתור לשירותים שלנו – שקוף עם פס זהב */
.hero-cta-row .btn-outline {
  background: rgba(255,255,255,0.08) !important; /* שקיפות עדינה */
  color: #ffffff !important; /* טקסט לבן */
  border: 1px solid #D4AF37 !important; /* פס זהב */
  padding: 0.78rem 2.2rem !important; /* אותו גודל כמו הראשי */
  font-weight: 700 !important;
  font-size: 0.92rem !important;
  border-radius: 3px !important; /* מרובע */
  letter-spacing: 0.05em !important;
  cursor: pointer !important;
}

.hero-cta-row .btn-outline:hover {
  background: rgba(212,175,55,0.18) !important; /* זהב שקוף עדין */
  border-color: #F2D37A !important; /* זהב בהיר יותר */
  color: #ffffff !important; /* טקסט נשאר לבן */
  transform: translateY(-2px); /* הרמה עדינה */
  transition: 0.25s ease-in-out;
}

/* הסתרה במובייל */
@media (max-width: 768px) {
  .hero-cta-row .btn-outline {
    display: none !important;
  }
}

/* Meta strip */
.hero-meta {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 2rem !important;
  margin-top: 0.5rem !important;
  padding-top: 1rem !important;
  border-top: 1px solid rgba(212,175,55,0.2) !important;
  width: 100% !important;
}
.hero-meta-item {
  color: rgba(245,240,230,0.65) !important;
  font-size: 0.78rem !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
  display: flex !important;
  align-items: center !important;
  gap: 0.45rem !important;
}
.hero-meta-dot {
  width: 5px !important;
  height: 5px !important;
  border-radius: 50% !important;
  background: #D4AF37 !important;
  display: inline-block !important;
  flex-shrink: 0 !important;
}



/* ── MOBILE ───────────────────────────────── */
@media (max-width: 768px) {
  .hero {
    height: 100svh !important;
    min-height: 100svh !important;
  }
  .hero-content {
    padding: 0 1.4rem 4rem !important;
    gap: 0.75rem !important;
  }
  .hero-title {
    font-size: clamp(1.7rem, 7.5vw, 2.2rem) !important;
    max-width: 100% !important;
  }
  .hero-subtitle { font-size: 0.88rem !important; max-width: 100% !important; }
  .ht-d { display: none !important; }
  .ht-m { display: block !important; }
  .hero-meta { gap: 1rem !important; }
}

/* HERO – TEXT CLARITY BOOST */
.hero-meta-item {
  color: rgba(255,255,255,0.92) !important;
  font-weight: 600 !important;
  text-shadow: 0 2px 14px rgba(0,0,0,0.55) !important;
}

.hero-badge {
  font-weight: 700 !important;
  color: #FFFDF8 !important;
  text-shadow: 0 2px 12px rgba(0,0,0,0.45) !important;
}

@media (max-width: 768px) {
  .hero-layer-bg {
    background-position: center 30% !important;
  }
}



    

    

    

    

    section {
