    }

    .quote strong {
      display: block;
      margin-top: 0.4rem;
      font-size: 0.85rem;
      color: var(--text-main);
    }

    .contact-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
      gap: 1.5rem;
    }

    .contact-item {
      font-size: 0.9rem;
      color: var(--text-soft);
      margin-bottom: 0.4rem;
    }

    .contact-item strong {
      display: inline-block;
      min-width: 80px;
    }

    .social-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin-top: 0.6rem;
    }

    .social-pill {
      display: inline-flex;
