/* ── Luxury Effects ── */
.card {
  position: relative;
  overflow: hidden;
  transform: translateY(0);
  transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
}
.card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at top, rgba(255,255,255,0.6), transparent 55%);
  opacity: 0;
  transition: opacity 0.25s ease;
  pointer-events: none;
}
.card:hover {
  transform: translateY(-6px);
  box-shadow: 0 18px 40px rgba(0,0,0,0.12);
  background: #fffdf8;
}
.card:hover::before {
  opacity: 1;
}

.workshop-photo,
.services-photo {
  transform: translateY(0) scale(1);
  transition: transform 0.35s ease, box-shadow 0.35s ease, filter 0.35s ease;
}
.workshop-photo::after,
.services-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.35), transparent 45%);
  opacity: 0;
  transition: opacity 0.35s ease;
}
.workshop-photo:hover,
.services-photo:hover {
  transform: translateY(-8px) scale(1.02);
  box-shadow: 0 24px 55px rgba(0,0,0,0.28);
  filter: saturate(1.08);
}
.workshop-photo:hover::after,
.services-photo:hover::after {
  opacity: 1;
}

