  border: 2px solid rgba(192, 157, 45, 0.708);
  box-shadow: 0 0 12px rgba(177, 147, 48, 0.788);

  background-color: rgba(205, 46, 46, 0.696);
  max-width: fit-content;
}
.start-link {
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-right: 10px;
}

.start-text {
  color: #ffffff !important;
  font-weight: 700;
  font-size: 1rem;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.475);
}

.hand-icon {
  font-size: 1.5rem;
  margin-left: 2px;
  transition: 0.25s ease;
}

.start-link:hover .hand-icon {
  transform: translateX(-4px) rotate(8deg);
}
#course-typing {
  white-space: pre-line;
}
@media (max-width: 600px) {
  .hero-subtitle.hero-course-line #course-typing {
    font-size: 0.95rem !important; /* תקטין או תגדיל לפי מה שנראה טוב */
    line-height: 1.35; /* שיהיה קריא ונעים */
  }
}
